// Shape the day's events into the few fields Jessie should reason about, and
// drop everything else.
//
// The raw Google payload was going straight to the model, and on 2026-08-30 it
// read `creator` - which is always howard@hitproductions.net, the account n8n
// authenticates with - and told Tara her own booking "was made by Howard, not
// you". Who booked something lives in the description as "Booked by: ...", and
// nothing else in a calendar event says it. A field she is not given is a field
// she cannot misread.
// Model output occasionally carries invisible characters. On 2026-08-30 a
// variation selector (U+FE0F) glued to the end of an ISO timestamp made Room
// Availability answer BAD_WINDOW, and the model then presented a booking
// summary as though the room were free. Every string the model hands this
// workflow is scrubbed once, here, rather than at each place one is read.
// Tabs and newlines survive - a description is allowed to contain them.
const clean = s => String(s == null ? '' : s)
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u200B-\u200F\u2028\u2029\u202A-\u202E\u2060-\u2064\uFE00-\uFE0F\uFEFF]/g, '')
  .trim();
const REQ = (function (o) {
  const out = {};
  for (const k in o) out[k] = (typeof o[k] === 'string') ? clean(o[k]) : o[k];
  return out;
})($('When Executed by Another Workflow').first().json || {});
const raw = $input.first().json || {};
const date = String(REQ.booking_date || '').trim();

const ROOMS = {
  'hitproductions.net_3737303833303637363538@resource.calendar.google.com': 'Studio 1',
  'c_18871bprki2umhrkjc4qcaldse1f8@resource.calendar.google.com': 'Studio 2',
  'c_1886me03bdcrki5bhu8vddknl472k@resource.calendar.google.com': 'Studio 3',
  'c_188e94dapvbp8jvrjmuga6qbof826@resource.calendar.google.com': 'Studio 4',
  'c_18889v3glj9cqiotg8j95jaqmdhmm@resource.calendar.google.com': 'Studio 5',
  'c_18838qt2ru30ein7gcefjiarplkre@resource.calendar.google.com': 'Studio 6',
  'c_188dupcj6cqfaipohqffj07ruq8de@resource.calendar.google.com': 'Studio 7',
  'c_18863v8hd6f42isegdh9i30psuo9q@resource.calendar.google.com': 'Studio 8',
  'c_18843dclutqm6hl9nbeg002phapfu@resource.calendar.google.com': 'Studio A',
  'c_1881vgb66tkpujjelnn3rniugd9pk@resource.calendar.google.com': 'Studio B',
  'c_188797f37eu9ujs6ldpf3smn78joc@resource.calendar.google.com': 'Studio C',
  'c_18801gc6ck77gho7jl0e1fug94u92@resource.calendar.google.com': 'Studio D',
  'c_18807te03d2sqh0lmtal9sbb04gao@resource.calendar.google.com': 'Studio E',
  'c_188em7d58podeju3i8q6juqlufkls@resource.calendar.google.com': 'Studio F',
  'c_1885k4adm87fqjd2j3j2usqftph5c@resource.calendar.google.com': 'Studio M',
  'c_1889v46vd62fkjk3i7r1hsfem7tcm@resource.calendar.google.com': 'M1',
  'c_1883ui6lnfc9ogt2hrmg57a30n72q@resource.calendar.google.com': 'M2',
  'c_188d7dkqgnfs6hu4iunlu5ogftct0@resource.calendar.google.com': 'M3',
  'c_18869nhmsj2uki8mljoi48v1cj7l4@resource.calendar.google.com': 'M4',
  'c_1889h30ci9noqjcbnoogad9qk75vq@resource.calendar.google.com': 'M5',
  'c_188f9gnq0a9tehf4g9ja57l83c0ts@resource.calendar.google.com': 'M6',
  'c_1880r9hhk9c2agpbko87o7fojosh0@resource.calendar.google.com': 'M7',
  'c_1884cu2cc84iujsjnu03s21f0ct9q@resource.calendar.google.com': 'M8',
  'c_1887hh5rsv6q4gt8hnu6ered170lg@resource.calendar.google.com': 'Salin',
  'c_1881169pcpn12gsnm6i7sc0gjk7gk@resource.calendar.google.com': 'Katha',
  'c_1886t6cjgrq0ihgpime01uibcqsg6@resource.calendar.google.com': 'Likha',
  'c_188227mpeagjuhi7gqlgns1di14be@resource.calendar.google.com': 'Lobby'
};
const NAMES = {};
for (const k in ROOMS) NAMES[ROOMS[k].toLowerCase()] = ROOMS[k];

if (!date) {
  return [{ json: { status: 'MISSING_DATE', bookings: [],
    human: 'No date was given, so nothing was looked up. Ask the requester which date the booking is on.' } }];
}
const items = Array.isArray(raw.items) ? raw.items : null;
if (!items) {
  return [{ json: { status: 'LOOKUP_FAILED', bookings: [],
    human: 'The calendar could not be read for that date. Tell the requester and offer to try again.' } }];
}

const hhmm = iso => {
  const d = new Date(iso);
  return d.toLocaleTimeString('en-US', { timeZone: 'Asia/Manila', hour: 'numeric', minute: '2-digit' });
};
// Department bookings are whole days written as midnight-to-midnight timestamps
// rather than as date-only events, so they came out "12:00 AM - 12:00 AM".
const isWholeDay = (s, e) => {
  if (!s || !e) return false;
  const m = iso => new Date(iso).toLocaleString('en-US',
    { timeZone: 'Asia/Manila', hour: '2-digit', minute: '2-digit', hour12: false });
  return m(s) === '00:00' && m(e) === '00:00';
};
const roomOf = ev => {
  const found = [];
  for (const a of (ev.attendees || [])) {
    const nm = ROOMS[String(a.email || '').toLowerCase()];
    if (nm && found.indexOf(nm) === -1) found.push(nm);
  }
  if (found.length) return found.join(' + ');
  const loc = String(ev.location || '').toLowerCase();
  for (const key in NAMES) if (loc.indexOf(key) !== -1) return NAMES[key];
  const first = String(ev.summary || '').split(' - ')[0].trim();
  return NAMES[first.toLowerCase()] || '';
};

const bookings = [];
for (const ev of items) {
  if (!ev || ev.status === 'cancelled') continue;
  const desc = String(ev.description || '');
  const by = desc.match(/Booked by:\s*([^|]+)/);
  const eng = desc.match(/Engineer:\s*([^|]+)/);
  const s = (ev.start || {}).dateTime, e = (ev.end || {}).dateTime;
  bookings.push({
    id: ev.id,
    title: ev.summary || '(no title)',
    time: (!s || !e || isWholeDay(s, e)) ? 'all day' : hhmm(s) + ' - ' + hhmm(e),
    room: roomOf(ev) || 'not identifiable',
    booked_by: by ? by[1].trim() : 'not recorded - made outside Jessie',
    engineer: eng ? eng[1].trim() : ''
  });
}

return [{ json: { status: 'OK', date: date, count: bookings.length, bookings: bookings,
  human: bookings.length
    ? 'These are the bookings on ' + date + '. "booked_by" is who made the booking; there is no other '
      + 'source for that. Use the id exactly as given if you cancel or move one.'
    : 'Nothing is booked on ' + date + '. Tell the requester and ask them to check the date.' } }];

